#pragma once
// Minimal D3D11 text overlay drawn into the game's backbuffer from the Present hook (before the real Present).
// Own bitmap font (render/font8x16.h, generated by tools/fontgen.cpp) and own shaders (render/overlay.hlsl,
// compiled with fxc by build.cmd); no third-party UI. The game's pipeline state is saved before drawing and
// restored afterwards, so the game never sees a change.
#include <cstdint>
#include <string>
#include <vector>

struct IDXGISwapChain;

namespace mc::render {

struct OverlayLine {
    std::string text;  // UTF-8; characters outside ASCII are drawn as '?', except the em dash (drawn as '-')
    uint32_t color;    // 0xAARRGGBB
};

class Overlay {
public:
    // Draws the lines as a small panel at the top-left of the backbuffer. Creates its resources on first use (and
    // again if the game's device changes). Disables itself (logged once) if anything fails.
    static void Draw(IDXGISwapChain* swapChain, const std::vector<OverlayLine>& lines);
    // Must run before IDXGISwapChain::ResizeBuffers: drops our reference to the backbuffer.
    static void ReleaseTargets();
};

} // namespace mc::render
